arguments.command:
for tool in qpdf pdftk gs libreoffice soffice pandoc fpdf; do command -v $tool >/dev/null 2>&1 && echo "FOUND: $tool"; done; echo "---python modules---"; python3 -c "
import importlib
for m in ['reportlab','fpdf','fpdf2','PyPDF2','pypdf','pdfplumber','pdfkit','weasyprint','img2pdf']:
    try:
        importlib.import_module(m)
        print('OK', m)
    except Exception as e:
        print('MISSING', m)
"
